const q = $json.query || {};
const bd = ($json.body && typeof $json.body === 'object') ? $json.body : {};
const hdr = $json.headers || {};
const b = Object.assign({}, bd, q);
const EXPECTED = 'YOUR_SHARED_SECRET'; // any long random string, sent as ?secret=
const provided = q.secret || bd.secret || hdr['x-webhook-secret'] || '';
if (provided !== EXPECTED) { throw new Error('unauthorized'); }
const raw = (b.url || b.link || '').trim();
let url = raw;
if (url) { url = url.split('?')[0]; if (!url.endsWith('/')) url += '/'; }
if (!url) { throw new Error('No url in payload'); }
const format = /\/(reel|tv)\//i.test(raw) ? 'Reel' : (/\/p\//i.test(raw) ? 'Post' : 'Reel');
const source = (b.source || 'unknown').toString();
const username = (b.username || '').toString();
const thumbnail = (b.thumbnail || '').toString();
return [{ json: { url, format, source, username, thumbnail } }];

// Optional: describe who is saving these reels, so titles fit your niche.
const CREATOR_CONTEXT = 'a creator who runs an online business';

const all = $input.all().map(x => x.json);
let rec = all[0];
if (Array.isArray(rec)) rec = rec[0];
rec = rec || {};
const n = $('Normalize').item.json;
const caption = (rec.caption || '').toString().slice(0, 2000);
const transcript = (rec.transcript || '').toString().slice(0, 4000);
const username = (rec.ownerUsername || n.username || '').toString();
const fullName = (rec.ownerFullName || '').toString();
const thumbnail = (rec.displayUrl || n.thumbnail || '').toString();
const views = rec.videoViewCount || rec.videoPlayCount || '';
const likes = rec.likesCount || '';
const enrichPrompt =
  'You analyze Instagram reels that ' + CREATOR_CONTEXT + ' saved as short-form inspiration. '
  + 'Return ONLY a JSON object, no prose, no code fences: {"title": string, "hook": string, "summary": string}. '
  + 'title = 3 to 8 words, the content idea the creator could make from this, punchy, no hashtags, no emojis, no trailing period. '
  + 'hook = one sentence naming the hook technique in the opening and why it stops the scroll. '
  + 'summary = 1 to 2 sentences on what the reel is about and the angle worth stealing. '
  + 'Never use dashes (em dash, en dash, or hyphen) as punctuation anywhere in title, hook, or summary. Use commas or periods instead. '
  + 'If transcript and caption are both empty, infer from the author and set title to "Saved reel from @' + (username || 'unknown') + '" and summary to "No transcript available, open the reel to review.". '
  + '\n\nAuthor: @' + username + (fullName ? (' (' + fullName + ')') : '')
  + '\nStats: ' + views + ' views, ' + likes + ' likes'
  + '\nCaption: ' + caption
  + '\nTranscript: ' + transcript;
return [{ json: { url: n.url, format: n.format, username, thumbnail, caption, transcript, enrichPrompt } }];

const be = $('Build enrich').item.json;
let title = '', hook = '', summary = '';
try {
  const txt = ($json.content && $json.content[0] && $json.content[0].text) ? $json.content[0].text : '';
  const cleaned = txt.replace(/```json/gi, '').replace(/```/g, '').trim();
  const m = cleaned.match(/\{[\s\S]*\}/);
  const o = JSON.parse(m ? m[0] : cleaned);
  title = (o.title || '').toString().slice(0, 120);
  hook = (o.hook || '').toString();
  summary = (o.summary || '').toString();
} catch (e) { /* defaults */ }
if (!title) title = be.username ? ('Saved reel from @' + be.username) : 'Saved reel';
const ideaCard = summary ? (title + '. ' + summary) : title;
const raw = {
  'URL': be.url,
  'Platform': 'Instagram',
  'Format': be.format,
  'Source Username': be.username,
  'Thumbnail': be.thumbnail,
  'Caption': be.caption,
  'Transcript': be.transcript,
  'Idea Card': ideaCard,
  'Hook Analysis': hook,
  'Status': 'New',
  'Saved At': $now.toISO(),
};
const fields = {};
for (const k in raw) { const v = raw[k]; if (v !== undefined && v !== null && v !== '') fields[k] = v; }
return [{ json: { fields } }];
